# replicate diagnostic selected rectangles for each color

def rects(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]; print('bg',bg)
 for color in set(x for row in grid for x in row)-{bg}:
  cand=[]
  for r1 in range(h):
   for r2 in range(r1+1,h):
    for c1 in range(w):
     for c2 in range(c1+1,w):
      area=(r2-r1+1)*(c2-c1+1); n=sum(grid[r][c]==color for r in range(r1,r2+1) for c in range(c1,c2+1))
      if n>=4 and n/area>=.62: cand.append((area,n,n/area,r1,r2,c1,c2))
  cand.sort(reverse=True); used=set(); selected=[]
  for area,n,d,r1,r2,c1,c2 in cand:
   pts={(r,c) for r in range(r1,r2+1) for c in range(c1,c2+1) if grid[r][c]==color}; fresh=pts-used
   if len(fresh)>=4 and len(fresh)/area>=.62:
    selected.append((r1,r2,c1,c2,area,len(fresh),round(len(fresh)/area,2))); used|=pts
  print(color,selected)
